import { Injectable, UnauthorizedException, BadRequestException } from '@nestjs/common';
import { UsersService } from '../users/users.service.js';
import { PrismaService } from '../prisma/prisma.service.js';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { Resend } from 'resend';

@Injectable()
export class AuthService {
  private resend: Resend;

  constructor(
    private usersService: UsersService,
    private prisma: PrismaService,
    private jwtService: JwtService
  ) {
    this.resend = new Resend(process.env.RESEND_API_KEY);
  }

  async checkUsername(username: string) {
    if (!username) return { available: false };
    const user = await this.usersService.findOneByUsername(username);
    return { available: !user };
  }

  async verifyTurnstile(token: string) {
    if (!token) throw new UnauthorizedException('Token Turnstile tidak ditemukan');
    const secret = process.env.TURNSTILE_SECRET;
    if (!secret) throw new UnauthorizedException('Konfigurasi Turnstile belum diatur di server');
    
    const res = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: `secret=${secret}&response=${token}`,
    });
    const data = await res.json();
    if (!data.success) {
      throw new UnauthorizedException('Verifikasi Anti-Spam gagal');
    }
    return true;
  }

  async register(data: any) {
    if (data.turnstileToken) {
      await this.verifyTurnstile(data.turnstileToken);
    }
    // 1. Cek apakah email atau username udah beneran terdaftar di tabel User asli
    const existingUser = await this.usersService.findOneByEmail(data.email);
    if (existingUser) throw new BadRequestException('Email sudah terdaftar dan aktif');

    const existingUsername = await this.usersService.findOneByUsername(data.username);
    if (existingUsername) throw new BadRequestException('Username sudah dipakai');

    const hashedPassword = await bcrypt.hash(data.password, 10);
    
    // 2. Generate 6 digit OTP
    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();

    // 3. Masukin ke tabel "Karantina" (PendingUser), bukan tabel User asli
    await this.prisma.pendingUser.upsert({
      where: { email: data.email },
      update: {
        username: data.username,
        passwordHash: hashedPassword,
        otpCode: otpCode,
        createdAt: new Date()
      },
      create: {
        email: data.email,
        username: data.username,
        passwordHash: hashedPassword,
        otpCode: otpCode,
      }
    });

    // 4. Kirim Email OTP
    try {
      await this.resend.emails.send({
        from: 'Mencari.online <noreply@mencari.online>', 
        to: data.email,
        subject: 'Kode Verifikasi Akun Mencari.online',
        html: `
        <!DOCTYPE html>
        <html>
        <head>
          <style>
            body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f7f6; margin: 0; padding: 0; }
            .container { max-width: 600px; margin: 40px auto; background-color: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.05); }
            .header { background-color: #047857; padding: 30px 20px; text-align: center; }
            .logo { max-width: 320px; height: auto; }
            .content { padding: 40px 30px; color: #333333; text-align: center; }
            .title { font-size: 24px; font-weight: bold; margin-bottom: 20px; color: #1f2937; }
            .otp-box { background-color: #f3f4f6; border: 2px dashed #cbd5e1; border-radius: 8px; padding: 20px; margin: 30px 0; font-size: 36px; font-weight: 800; letter-spacing: 8px; color: #047857; }
            .footer { background-color: #f8fafc; padding: 20px; text-align: center; font-size: 12px; color: #64748b; border-top: 1px solid #e2e8f0; }
          </style>
        </head>
        <body>
          <div class="container">
            <div class="header">
              <img src="data:image/png;base64," alt="Mencari.online Logo" class="logo" />
            </div>
            <div class="content">
              <div class="title">Halo, ${data.username}!</div>
              <p>Terima kasih telah mendaftar di <strong>Mencari.online</strong>. Untuk menyelesaikan pendaftaran akun lu, silakan masukkan kode verifikasi berikut:</p>
              <div class="otp-box">${otpCode}</div>
              <p style="font-size: 14px; color: #64748b;">Kode ini hanya berlaku selama 10 menit. Jangan berikan kode ini kepada siapa pun.</p>
            </div>
            <div class="footer">
              &copy; ${new Date().getFullYear()} Mencari.online. All rights reserved.<br/>
              Email ini dikirim secara otomatis, mohon tidak dibalas.
            </div>
          </div>
        </body>
        </html>
        `
      });
    } catch (error) {
      console.error("Gagal mengirim OTP via Resend:", error);
    }

    return { message: "Data diamankan sementara, silakan cek email untuk kode OTP.", email: data.email };
  }

  async verifyOtp(data: { email: string, code: string }) {
    // 1. Cari user di tabel Karantina (PendingUser)
    const pending = await this.prisma.pendingUser.findUnique({ where: { email: data.email } });
    
    if (!pending) throw new BadRequestException('Email tidak ditemukan atau sudah diverifikasi');
    if (pending.otpCode !== data.code) throw new BadRequestException('Kode OTP salah');

    // 2. Kalau OTP bener, baru kita masukin ke tabel User asli
    await this.usersService.create({
      username: pending.username,
      email: pending.email,
      passwordHash: pending.passwordHash,
      profile: {
        create: {
          displayName: pending.username,
        }
      }
    });

    // 3. Hapus data dari tabel Karantina biar bersih
    await this.prisma.pendingUser.delete({ where: { email: pending.email } });

    return { message: "Akun berhasil diverifikasi dan dimasukkan ke database utama! Silakan login." };
  }

  async login(user: any) {
    if (user.turnstileToken) {
      await this.verifyTurnstile(user.turnstileToken);
    }
    let userData = user;
    if (user.password) {
      const identifier = user.identifier || user.email;
      userData = await this.usersService.findOneByEmailOrUsername(identifier);
      if (!userData) throw new UnauthorizedException('Kredensial salah');
      
      const isPasswordValid = await bcrypt.compare(user.password, userData.passwordHash);
      if (!isPasswordValid) throw new UnauthorizedException('Kredensial salah');
    }

    // Sekarang nggak perlu cek isVerified lagi, karena kalau udah ada di tabel User berarti pasti udah lolos verifikasi.

    const payload = { username: userData.username, sub: userData.id };
    return {
      access_token: this.jwtService.sign(payload),
      user: {
        id: userData.id,
        username: userData.username,
        email: userData.email
      }
    };
  }

  async forgotPassword(data: any) {
    if (data.turnstileToken) {
      await this.verifyTurnstile(data.turnstileToken);
    }
    
    const identifier = data.identifier;
    const user = await this.usersService.findOneByEmailOrUsername(identifier);
    if (!user) throw new BadRequestException('Akun tidak ditemukan');

    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 menit

    await this.prisma.user.update({
      where: { id: user.id },
      data: { resetOtpCode: otpCode, resetOtpExpiresAt: expiresAt }
    });

    try {
      await this.resend.emails.send({
        from: 'Mencari.online <noreply@nearhomey.email>',
        to: user.email,
        subject: 'Reset Password - Mencari.online',
        html: `Kode OTP reset password lu adalah: <strong>${otpCode}</strong>. Kode ini berlaku selama 10 menit.`
      });
    } catch (e) {
      console.error(e);
    }

    return { message: "Kode OTP telah dikirim ke email.", email: user.email };
  }

  async resetPassword(data: any) {
    const user = await this.prisma.user.findFirst({
      where: { email: data.email, resetOtpCode: data.otp }
    });

    if (!user) throw new BadRequestException('OTP salah atau tidak ditemukan');
    if (!user.resetOtpExpiresAt || user.resetOtpExpiresAt < new Date()) {
      throw new BadRequestException('OTP sudah kadaluarsa');
    }

    const hashedPassword = await bcrypt.hash(data.password, 10);
    
    await this.prisma.user.update({
      where: { id: user.id },
      data: {
        passwordHash: hashedPassword,
        resetOtpCode: null,
        resetOtpExpiresAt: null
      }
    });

    return { message: "Password berhasil diubah" };
  }
}
